text:
{
 "lead": {
  "es": "人事院《じんじいん》（国《くに》の公務員《こうむいん》の給料《きゅうりょう》について意見《いけん》を出《だ》す役所《やくしょ》）は、令和《れいわ》7年《ねん》8月《がつ》7日《か》に、給料《きゅうりょう》を変《か》えるようにすすめました（勧告《かんこく》）。それを受《う》けて、国《くに》の一般《いっぱん》の公務員《こうむいん》の、月《つき》の給料《きゅうりょう》（俸給月額《ほうきゅうげつがく》）や、ボーナス（期末手当《きまつてあて》・勤勉手当《きんべんてあて》）、そのほかの手当《てあて》の額《がく》を変《か》える法律《ほうりつ》です。",
  "hs": "人事院（国家公務員の給与《きゅうよ》などについて勧告《かんこく》を出す国の機関）の令和7年8月7日付けの給与《きゅうよ》改定｜勧告《かんこく》を受け、一般職《いっぱんしょく》の国家公務員の俸給月額《ほうきゅうげつがく》（月の基本給）や、期末手当、勤勉手当（ボーナス）、その他の手当の額を改定する法律です。"
 },
 "facts/0/text": {
  "es": "すべての給料《きゅうりょう》の表《ひょう》（俸給表《ほうきゅうひょう》）で、月《つき》の給料《きゅうりょう》を上《あ》げます。はじめの給料《きゅうりょう》（初任給《しょにんきゅう》）をはじめ、若《わか》い人《ひと》の給料《きゅうりょう》に、とくに力《ちから》を入《い》れます。",
  "hs": "すべての俸給表《ほうきゅうひょう》（給料の表）の俸給月額《ほうきゅうげつがく》を、初任給をはじめ若い世代に重点を置きながら引き上げます。"
 },
 "facts/1/text": {
  "es": "2つのボーナス（期末手当《きまつてあて》と勤勉手当《きんべんてあて》）の割合《わりあい》を、それぞれ1年《ねん》で0.025月分《つきぶん》上《あ》げます。",
  "hs": "期末手当と勤勉手当（ボーナス）の支給割合を、それぞれ年間0.025月分引き上げます。"
 },
 "facts/2/text": {
  "es": "国《くに》の役所《やくしょ》の本部《ほんぶ》で働《はたら》く人《ひと》の手当《てあて》（本《ほん》府省《ふしょう》業務《ぎょうむ》調整《ちょうせい》手当《てあて》）をもらえる人《ひと》をふやします。また、もらえる額《がく》の上《うえ》のかぎりの割合《わりあい》を上《あ》げます。遠《とお》くの土地《とち》で働《はたら》く人《ひと》の手当《てあて》ににた手当《てあて》（特地《とくち》勤務手当《きんむてあて》に準《じゅん》ずる手当《てあて》）は、新《あたら》しく給料《きゅうりょう》の表《ひょう》が当《あ》てはまる人《ひと》になった人《ひと》も、もらえるようにします。",
  "hs": "本府省業務調整手当（中央省庁で働く職員の手当）の支給対象の職員を広げ、支給月額の上限の割合を引き上げます。特地勤務手当に準ずる手当（へき地などで働く人の手当に準じた手当）は、新たに俸給表《ほうきゅうひょう》の適用を受ける職員になった人も支給対象とします。"
 },
 "facts/3/text": {
  "es": "新《あたら》しい手当《てあて》（第《だい》二《に》種《しゅ》初任給《しょにんきゅう》調整《ちょうせい》手当《てあて》）をつくります。毎月《まいつき》の給料《きゅうりょう》が、地域《ちいき》ごとの一番《いちばん》ひくい給料《きゅうりょう》のきまり（地域別《ちいきべつ》最低賃金《さいていちんぎん》）にあたる額《がく》を、下回《したまわ》らないようにします。",
  "hs": "新たに第二種初任給調整手当をつくり、毎月の給与《きゅうよ》が地域別最低賃金（地域ごとに決まった最低の賃金）に相当する額を下回らない水準になるようにします。"
 },
 "facts/4/text": {
  "es": "通勤《つうきん》のための駐車場《ちゅうしゃじょう》などについての手当《てあて》を、新《あたら》しくつくります。1か月《げつ》の駐車場《ちゅうしゃじょう》などの料金《りょうきん》にあたる額《がく》を、5000円《えん》をこえないはんいで、はらいます。",
  "hs": "新たに駐車場《ちゅうしゃじょう》などについての通勤手当をつくり、1か月の駐車場《ちゅうしゃじょう》などの料金に相当する額を、5000円を超《こ》えない範囲《はんい》で支給します。"
 },
 "facts/5/text": {
  "es": "この法律《ほうりつ》は、公布《こうふ》（世《よ》の中《なか》に知《し》らせること）の日《ひ》から使《つか》われます。ただし、第《だい》二《に》種《しゅ》初任給《しょにんきゅう》調整《ちょうせい》手当《てあて》と、駐車場《ちゅうしゃじょう》などについての通勤手当《つうきんてあて》は、令和《れいわ》8年《ねん》4月《がつ》｜1日《ついたち》から使《つか》われます。給料《きゅうりょう》の表《ひょう》、ボーナス（期末手当《きまつてあて》・勤勉手当《きんべんてあて》）、本《ほん》府省《ふしょう》業務《ぎょうむ》調整《ちょうせい》手当《てあて》、特地《とくち》勤務手当《きんむてあて》に準《じゅん》ずる手当《てあて》を変《か》えることは、令和《れいわ》7年《ねん》4月《がつ》｜1日《ついたち》にさかのぼって当《あ》てはめます。",
  "hs": "この法律は、公布（世の中に知らせること）の日から施行《しこう》（効力が始まること）します。ただし、第二種初任給調整手当と駐車場《ちゅうしゃじょう》などについての通勤手当は令和8年4月1日から施行《しこう》し、俸給表《ほうきゅうひょう》、期末手当・勤勉手当、本府省業務調整手当、特地勤務手当に準ずる手当の改定は、令和7年4月1日にさかのぼって適用します。"
 },
 "more/reason/text": {
  "es": "内閣《ないかく》は、こう説明《せつめい》しています。人事院《じんじいん》が、令和《れいわ》7年《ねん》8月《がつ》7日《か》に、給料《きゅうりょう》を変《か》えるようにすすめました（勧告《かんこく》）。それを受《う》けて、国《くに》の一般《いっぱん》の公務員《こうむいん》の、月《つき》の給料《きゅうりょう》や、いくつもの手当《てあて》、ボーナスの額《がく》を変《か》える必要《ひつよう》があるためです。手当《てあて》をもらえる人《ひと》を広《ひろ》げることや、新《あたら》しい手当《てあて》（第《だい》二《に》種《しゅ》初任給《しょにんきゅう》調整《ちょうせい》手当《てあて》）をつくること、駐車場《ちゅうしゃじょう》などについての通勤手当《つうきんてあて》をはらうことなども、ふくまれます。",
  "hs": "内閣は、人事院の令和7年8月7日付けの給与《きゅうよ》改定｜勧告《かんこく》をふまえ、一般職《いっぱんしょく》の国家公務員の俸給月額《ほうきゅうげつがく》、初任給調整手当、通勤手当、宿日直手当、期末手当と勤勉手当、非常勤の委員などの手当の額を改定する必要があるためとしている。本府省業務調整手当の対象職員の拡大と上限割合の改定、第二種初任給調整手当の新設、駐車場《ちゅうしゃじょう》等に係る通勤手当の支給なども行う必要があるとしている。"
 },
 "more/who/text": {
  "es": "国《くに》の一般《いっぱん》の公務員《こうむいん》（一般職《いっぱんしょく》の国家公務員《こっかこうむいん》）です。この中《なか》には、本《ほん》府省《ふしょう》業務《ぎょうむ》調整《ちょうせい》手当《てあて》をもらう人《ひと》、新《あたら》しく給料《きゅうりょう》の表《ひょう》（俸給表《ほうきゅうひょう》）が当《あ》てはまる人《ひと》になった人《ひと》、駐車場《ちゅうしゃじょう》などを使《つか》う人《ひと》もふくまれます。また、非常勤《ひじょうきん》（毎日《まいにち》ではなく働《はたら》く人《ひと》）の委員《いいん》・顧問《こもん》・参与《さんよ》などです。",
  "hs": "一般職《いっぱんしょく》の国家公務員（本府省業務調整手当の支給対象の職員、新たに俸給表《ほうきゅうひょう》の適用を受ける職員になった人、駐車場《ちゅうしゃじょう》などを利用する職員をふくむ）と、非常勤の委員・顧問《こもん》・参与《さんよ》など。"
 },
 "more/committee/text": {
  "es": "衆議院《しゅうぎいん》の内閣委員会《ないかくいいんかい》は、一般職《いっぱんしょく》と特別職《とくべつしょく》の給料《きゅうりょう》についての2つの法律《ほうりつ》の案《あん》を話《はな》し合《あ》いました。12月《がつ》8日《か》に案《あん》をまかされ、10日《か》に松本《まつもと》国務大臣《こくむだいじん》から説明《せつめい》を聞《き》きました。11日《にち》に質問《しつもん》をしました。意見《いけん》をのべ合《あ》ったあと、順番《じゅんばん》に決《けつ》をとりました。2つとも賛成《さんせい》が多《おお》く、そのまま通《とお》すことに決《き》まりました。参議院《さんぎいん》の内閣委員会《ないかくいいんかい》も、2つの案《あん》をいっしょに話《はな》し合《あ》いました。一般職《いっぱんしょく》の給料《きゅうりょう》の変《か》え方《かた》や、働《はたら》く人《ひと》を集《あつ》める方法《ほうほう》、大臣《だいじん》などの給料《きゅうりょう》のあつかいなどについて、質問《しつもん》がありました。日本共産党《にほんきょうさんとう》は賛成《さんせい》、れいわ新選組《しんせんぐみ》は反対《はんたい》の意見《いけん》をのべました。決《けつ》をとった結果《けっか》、賛成《さんせい》が多《おお》く、そのまま通《とお》すことに決《き》まりました。",
  "hs": "衆議院内閣委員会は、一般職《いっぱんしょく》と特別職の給与《きゅうよ》に関する2つの法律案を審査《しんさ》した。12月8日に付託《ふたく》され（審査《しんさ》を任され）、10日に松本国務大臣から趣旨《しゅし》の説明を聞き、11日に質疑を行った。討論の後に順に採決し、両案とも賛成多数で原案のとおり可決すべきものとした。参議院内閣委員会も両法律案をまとめて審査《しんさ》し、一般職《いっぱんしょく》の給与《きゅうよ》改定の在り方と人材確保策、閣僚《かくりょう》などの給与《きゅうよ》の取扱《とりあつか》いなどについて質疑があった。討論では日本共産党が賛成、れいわ新選組が反対の意見を述べ、採決の結果、多数で原案どおり可決すべきものとした。"
 },
 "more/views/0/text": {
  "es": "日本共産党《にほんきょうさんとう》は、賛成《さんせい》するとのべました。物価《ぶっか》がとても上《あ》がっている中《なか》では、まだ十分《じゅうぶん》な高《たか》さではないとしました。それでも、国《くに》の公務員《こうむいん》の給料《きゅうりょう》を上《あ》げるものだからだと、理由《りゆう》をのべました。",
  "hs": "日本共産党は、厳しい物価｜高騰《こうとう》（物の値段が大きく上がること）の下では不十分な水準ではあるものの、国家公務員の給与《きゅうよ》を引き上げるものであることを理由に、一般職給与法《いっぱんしょくきゅうよほう》改正案に賛成すると述べた。"
 },
 "more/views/1/text": {
  "es": "れいわ新選組《しんせんぐみ》は、反対《はんたい》しました。公務員《こうむいん》の給料《きゅうりょう》を上《あ》げても、物価《ぶっか》の上《あ》がり方《かた》に追《お》いつかず、十分《じゅうぶん》ではないとしました。人事院《じんじいん》がすすめた3.62％をこえて、大《おお》きく上《あ》げることが必要《ひつよう》だとのべました。",
  "hs": "れいわ新選組は、公務員の給与《きゅうよ》の引上げが物価高に追いつかない不十分な内容だとし、人事院勧告《じんじいんかんこく》の3.62％を超《こ》える大幅《おおはば》な引上げが必要だと述べて反対した。"
 }
}
